<?php
/**
 * Generated by bin/build.sh --free from pro/licensorpro-client/free-bootstrap.php.tpl
 * (canonical copy: LicensorPro sdk/licensorpro-client/). DO NOT EDIT.
 *
 * Boots the licensing SDK and nothing else, so this build can update itself.
 * It contains no premium code: the --free build deletes pro/ wholesale and puts
 * only pro/licensorpro-client/ back.
 *
 * Why this build exists at all: wordpress.org forbids self-updating plugins, so
 * the Lite build ships no updater. That rule applies to .org, not to a build we
 * hand out ourselves, and with the .org listings closed since 20 Aug the Lite
 * build cannot be updated by anyone, including for security fixes.
 *
 * One template for every JnK plugin, so the free builds behave the same: the
 * same license card in the same place, the same "View details", the same key
 * adoption. Only the identifiers below differ.
 */
if ( ! defined( 'ABSPATH' ) ) { exit; }

$lp_sdk = __DIR__ . '/licensorpro-client/licensorpro-client.php';
if ( ! file_exists( $lp_sdk ) ) { return; }
require_once $lp_sdk;
if ( ! class_exists( 'LicensorPro_Client' ) ) { return; }

$lp_client = new \LicensorPro_Client( [
    'product_slug'   => 'entryvault',
    'plugin_file'    => ENTRYVAULT_FILE,
    'plugin_version' => ENTRYVAULT_VERSION,
    'plugin_name'    => 'EntryVault',
    'text_domain'    => 'entryvault',
    'menu_slug'      => 'entryvault-license',
    // A free build: its licence only exists so it can update itself. No expiry
    // or revoke notices (there are no Pro tools to lock), no "enter your Pro key".
    'pro_build'       => false,
    'licence_notices' => false,
    'card_hook'       => 'entryvault_settings_after',
    'settings_url'    => admin_url( 'admin.php?page=entryvault-settings#lp-entryvault-license' ),
    'support_url'     => 'https://jnkplugins.com/contact',
    'account_url'     => 'https://license.jnkplugins.com/account/licenses',
] );
$lp_client->init();

// An older SDK copy loaded first by another plugin ignores card_hook.
if ( ! method_exists( $lp_client, 'is_free_licence' ) ) {
    add_action( 'entryvault_settings_after', [ $lp_client, 'render_settings_page' ] );
}

/**
 * "View details" on the Plugins screen: the licence server describes the paid
 * product, so the free build showed the Pro description and changelog. Show what
 * this zip's own readme.txt says instead.
 */
add_filter( 'plugins_api', static function ( $result, $action, $args ) {
    if ( 'plugin_information' !== $action || ! is_object( $args ) || 'entryvault' !== ( $args->slug ?? '' ) || ! is_object( $result ) ) {
        return $result;
    }
    $readme = dirname( __DIR__ ) . '/readme.txt';
    if ( ! is_readable( $readme ) ) {
        return $result;
    }
    $text     = (string) file_get_contents( $readme );
    $sections = [];
    foreach ( [ 'description' => 'Description', 'changelog' => 'Changelog', 'faq' => 'Frequently Asked Questions' ] as $key => $heading ) {
        if ( preg_match( '/^==\s*' . preg_quote( $heading, '/' ) . '\s*==\s*$(.*?)(?=^==\s|\z)/ms', $text, $m ) ) {
            $body = trim( $m[1] );
            $body = preg_replace( '/^=\s*(.+?)\s*=\s*$/m', '<h4>$1</h4>', esc_html( $body ) );
            $body = preg_replace( '/^\*\s+(.+)$/m', '<li>$1</li>', $body );
            $sections[ $key ] = wpautop( $body );
        }
    }
    if ( $sections ) {
        $result->sections = array_merge( (array) ( $result->sections ?? [] ), $sections );
    }
    if ( preg_match( '/^\s*(.+?)\s*$/m', (string) preg_replace( '/^===.*===\s*$|^[A-Za-z ]+:.*$/m', '', explode( '==', $text )[0] ?? '' ), $short ) ) {
        $result->short_description = trim( $short[1] );
    }
    return $result;
}, 20, 3 );

/**
 * Adopt the licence key stamped into this zip at download time.
 *
 * The key is bound to the site by activate(), not merely stored: storing the
 * option alone would leave the install unactivated and every update check would
 * be refused.
 *
 * Runs once. A failure is retried on a later admin request rather than looped:
 * the licence server being briefly unreachable must not turn into a request per
 * page load.
 */
add_action( 'admin_init', static function () use ( $lp_client ) {
    $opt = 'licensorpro_' . 'entryvault' . '_key';
    if ( '' !== (string) get_option( $opt, '' ) ) { return; }

    $attempted = 'licensorpro_entryvault_free_claimed';
    if ( get_transient( $attempted ) ) { return; }

    $stamp = dirname( __DIR__ ) . '/licensorpro-free.json';
    if ( ! file_exists( $stamp ) ) { return; }

    $data = json_decode( (string) file_get_contents( $stamp ), true );
    $key  = is_array( $data ) ? (string) ( $data['license_key'] ?? '' ) : '';
    if ( '' === $key ) { return; }

    set_transient( $attempted, 1, HOUR_IN_SECONDS );
    $lp_client->activate( $key );
}, 20 );
